//! `Frame::StreamParams` (oxideav-core 0.1.43): the decoder announces a
//! mid-stream change of its output description in band, immediately
//! before the first frame of the new shape.
//!
//! Gates, on a black-box libx265 splice (`tests/fixtures/stream_params/`,
//! regenerated by `gen.sh` there, which records the size / pix_fmt
//! `ffprobe` reports for every output frame and the MD5 of each frame's
//! raw planes from a black-box decode of its segment alone):
//!
//! * seven segments — size + depth, an identical shape, size + chroma
//!   format + depth, the conformance window alone, the frame rate
//!   alone, the bit depth alone — give exactly one event per real
//!   change (five), none for the first shape and none for the segment
//!   repeating the previous shape;
//! * when the event is returned, `output_params()` equals its payload
//!   and the generation has moved by one; every frame matches the
//!   description in force, byte-exact against the segment decodes;
//! * the same holds one NAL per packet and the whole stream queued
//!   before the first receive (old-shape frames still in the reorder
//!   buffer drain before the event), at 1, 2, 4 and 8 worker threads;
//! * `reset()` (with a RASL picture skipped at the seek point) and
//!   `flush()` follow the same rule; the arena path skips the event;
//! * multi-layer streams (the crate's own layered fixtures and, when
//!   the workspace stages them, the official MV-HEVC / SHVC conformance
//!   bitstreams) emit no event for layer alternation within an access
//!   unit sequence: every event is a real change of the description;
//! * the encoder rejects the event with `Error::Unsupported`.

mod fixture_bytes;

use std::path::Path;

use fixture_bytes::md5;
use oxideav_core::{
    CodecId, CodecParameters, ColorSignal, Decoder, Error, ExecutionContext, Frame, LayerInfo,
    OutputParamsWatch, Packet, PixelFormat, Rational, TimeBase, VideoFrame,
};
use oxideav_h265::{make_decoder, make_encoder};

const DIR: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/stream_params");

/// The decoder-owned fields of an `output_params` answer.
#[derive(Clone, Debug, PartialEq)]
struct Desc {
    width: Option<u32>,
    height: Option<u32>,
    pixel_format: Option<PixelFormat>,
    frame_rate: Option<Rational>,
    color_signal: ColorSignal,
    layers: Vec<LayerInfo>,
}

impl Desc {
    fn of(p: &CodecParameters) -> Self {
        Self {
            width: p.width,
            height: p.height,
            pixel_format: p.pixel_format,
            frame_rate: p.frame_rate,
            color_signal: p.color_signal,
            layers: p.layers.clone(),
        }
    }
}

/// One `expected.txt` row.
#[derive(Clone, Debug, PartialEq)]
struct Expected {
    width: u32,
    height: u32,
    pixel_format: PixelFormat,
    md5: String,
}

fn expected() -> Vec<Expected> {
    let text = std::fs::read_to_string(format!("{DIR}/expected.txt")).expect("expected.txt");
    text.lines()
        .map(|l| {
            let f: Vec<&str> = l.split(',').collect();
            Expected {
                width: f[0].parse().unwrap(),
                height: f[1].parse().unwrap(),
                pixel_format: match f[2] {
                    "yuv420p" => PixelFormat::Yuv420P,
                    "yuv422p" => PixelFormat::Yuv422P,
                    "yuv420p10le" => PixelFormat::Yuv420P10Le,
                    "yuv422p10le" => PixelFormat::Yuv422P10Le,
                    other => panic!("unmapped pix_fmt {other}"),
                },
                md5: f[3].to_owned(),
            }
        })
        .collect()
}

fn spliced() -> Vec<u8> {
    std::fs::read(format!("{DIR}/spliced7.hevc")).expect("fixture")
}

/// Split an Annex B byte stream into NAL unit payloads (no start code).
fn nal_payloads(data: &[u8]) -> Vec<&[u8]> {
    let mut starts = Vec::new();
    let mut i = 0usize;
    while i + 3 <= data.len() {
        if data[i] == 0 && data[i + 1] == 0 && data[i + 2] == 1 {
            starts.push(i + 3);
            i += 3;
        } else {
            i += 1;
        }
    }
    (0..starts.len())
        .map(|k| {
            let mut end = starts.get(k + 1).map(|&s| s - 3).unwrap_or(data.len());
            while end > starts[k] && data[end - 1] == 0 {
                end -= 1;
            }
            &data[starts[k]..end]
        })
        .collect()
}

fn nal_type(n: &[u8]) -> u8 {
    (n[0] >> 1) & 0x3f
}

fn annexb(n: &[u8]) -> Packet {
    let mut d = vec![0, 0, 0, 1];
    d.extend_from_slice(n);
    Packet::new(0, TimeBase::new(1, 25), d)
}

/// Bytes per sample row / rows of each plane `pf` stores at `w` x `h`.
fn plane_geometry(pf: PixelFormat, w: usize, h: usize) -> Option<Vec<(usize, usize)>> {
    use PixelFormat::*;
    let (bps, sub, planes) = match pf {
        Gray8 => (1, (1, 1), 1),
        Gray10Le | Gray12Le | Gray16Le => (2, (1, 1), 1),
        Yuv420P => (1, (2, 2), 3),
        Yuv422P => (1, (2, 1), 3),
        Yuv444P => (1, (1, 1), 3),
        Yuv420P10Le | Yuv420P12Le | Yuv420P16Le => (2, (2, 2), 3),
        Yuv422P10Le | Yuv422P12Le | Yuv422P16Le => (2, (2, 1), 3),
        Yuv444P10Le | Yuv444P12Le | Yuv444P16Le => (2, (1, 1), 3),
        _ => return None,
    };
    let mut g = vec![(w * bps, h)];
    for _ in 1..planes {
        g.push((w.div_ceil(sub.0) * bps, h.div_ceil(sub.1)));
    }
    Some(g)
}

fn frame_geometry(vf: &VideoFrame) -> Vec<(usize, usize)> {
    vf.image_planes()
        .iter()
        .map(|pl| (pl.stride, pl.data.len() / pl.stride.max(1)))
        .collect()
}

/// Whether `vf` has the plane geometry `p` describes (`None` when `p`
/// names no planar layout this check knows).
fn frame_matches(vf: &VideoFrame, p: &CodecParameters) -> Option<bool> {
    let g = plane_geometry(p.pixel_format?, p.width? as usize, p.height? as usize)?;
    Some(frame_geometry(vf) == g)
}

fn frame_md5(vf: &VideoFrame) -> String {
    let bytes: Vec<u8> = vf
        .image_planes()
        .iter()
        .flat_map(|p| p.data.iter().copied())
        .collect();
    md5::hex(&bytes)
}

/// One item `receive_frame` returned.
#[derive(Debug)]
enum Item {
    /// A `StreamParams` event and its payload.
    Event(Desc),
    /// A video frame: its MD5, layer, whether it matched the
    /// description in force, and that description.
    Video {
        md5: String,
        layer: u16,
        matches: Option<bool>,
        geometry: Vec<(usize, usize)>,
        desc: Desc,
    },
}

/// Pull every item `dec` has ready, checking the core contract at each
/// one: an event's payload equals `output_params()` and comes with a
/// generation bump of exactly one; a frame never moves the generation.
fn pull(dec: &mut dyn Decoder, items: &mut Vec<Item>, last_gen: &mut u64, tag: &str) {
    loop {
        let f = match dec.receive_frame() {
            Ok(f) => f,
            Err(Error::NeedMore | Error::Eof) => return,
            Err(e) => panic!("{tag}: {e}"),
        };
        let now = dec.output_params().expect("answer after an item");
        let generation = dec.output_params_generation();
        match f {
            Frame::StreamParams(p) => {
                assert_eq!(
                    Desc::of(&p),
                    Desc::of(&now),
                    "{tag}: payload == output_params"
                );
                assert_eq!(generation, last_gen.wrapping_add(1), "{tag}: one bump");
                *last_gen = generation;
                items.push(Item::Event(Desc::of(&p)));
            }
            Frame::Video(vf) => {
                assert_eq!(generation, *last_gen, "{tag}: frames never bump");
                items.push(Item::Video {
                    md5: frame_md5(&vf),
                    layer: vf.layer().map_or(0, |l| l.layer_id),
                    matches: frame_matches(&vf, &now),
                    geometry: frame_geometry(&vf),
                    desc: Desc::of(&now),
                });
            }
            other => panic!("{tag}: unexpected {other:?}"),
        }
    }
}

fn decoder(threads: usize) -> Box<dyn Decoder> {
    let mut dec = make_decoder(&CodecParameters::video(CodecId::new("h265"))).expect("decoder");
    dec.set_execution_context(&ExecutionContext::with_threads(threads));
    dec
}

/// Decode one NAL per packet, pulling after each.
fn decode_streamed(bytes: &[u8], threads: usize, tag: &str) -> Vec<Item> {
    let mut dec = decoder(threads);
    let (mut items, mut g) = (Vec::new(), 0);
    for (i, nal) in nal_payloads(bytes).into_iter().enumerate() {
        dec.send_packet(&annexb(nal).with_pts(i as i64))
            .expect("send");
        pull(&mut *dec, &mut items, &mut g, tag);
    }
    dec.flush().expect("flush");
    pull(&mut *dec, &mut items, &mut g, tag);
    items
}

/// Queue the whole stream and flush before the first receive.
fn decode_whole(bytes: &[u8], threads: usize, tag: &str) -> Vec<Item> {
    let mut dec = decoder(threads);
    dec.send_packet(&Packet::new(0, TimeBase::new(1, 25), bytes.to_vec()).with_pts(0))
        .expect("send");
    dec.flush().expect("flush");
    let (mut items, mut g) = (Vec::new(), 0);
    pull(&mut *dec, &mut items, &mut g, tag);
    items
}

/// The frame indices the events precede, and the frames.
fn split(items: &[Item]) -> (Vec<usize>, Vec<&Item>) {
    let mut at = Vec::new();
    let mut frames = Vec::new();
    for it in items {
        match it {
            Item::Event(_) => at.push(frames.len()),
            Item::Video { .. } => frames.push(it),
        }
    }
    (at, frames)
}

/// Every frame byte-exact and shaped as `expected` says, under a
/// description that states exactly that shape.
fn assert_frames(frames: &[&Item], want: &[Expected], tag: &str) {
    assert_eq!(frames.len(), want.len(), "{tag}: frame count");
    for (i, (it, e)) in frames.iter().zip(want).enumerate() {
        let Item::Video {
            md5, matches, desc, ..
        } = it
        else {
            unreachable!()
        };
        assert_eq!(md5, &e.md5, "{tag}: frame {i} byte-exact");
        assert_eq!(matches, &Some(true), "{tag}: frame {i} geometry");
        assert_eq!(
            (desc.width, desc.height, desc.pixel_format),
            (Some(e.width), Some(e.height), Some(e.pixel_format)),
            "{tag}: frame {i} described"
        );
    }
}

/// a | b (size + depth) | c (same) | d (size + chroma + depth) |
/// e (conformance window) | f (rate) | g (depth): eight frames each.
const EVENTS_AT: [usize; 5] = [8, 24, 32, 40, 48];

#[test]
fn one_event_per_change_streamed_and_whole_at_several_worker_counts() {
    let bytes = spliced();
    let want = expected();
    assert_eq!(want.len(), 56);
    let mut reference: Option<Vec<Desc>> = None;
    for threads in [1, 2, 4, 8] {
        for (mode, items) in [
            ("streamed", decode_streamed(&bytes, threads, "streamed")),
            ("whole", decode_whole(&bytes, threads, "whole")),
        ] {
            let tag = format!("{mode} @{threads}");
            let (at, frames) = split(&items);
            assert_eq!(at, EVENTS_AT, "{tag}: events precede these frames");
            assert_frames(&frames, &want, &tag);
            // The rate-only change (segment f) moves the description,
            // not the planes.
            let rates: Vec<Option<Rational>> = items
                .iter()
                .filter_map(|it| match it {
                    Item::Event(d) => Some(d.frame_rate),
                    _ => None,
                })
                .collect();
            assert_eq!(rates[3], Some(Rational::new(50, 1)), "{tag}: rate event");
            let descs: Vec<Desc> = items
                .iter()
                .map(|it| match it {
                    Item::Event(d) => d.clone(),
                    Item::Video { desc, .. } => desc.clone(),
                })
                .collect();
            match &reference {
                None => reference = Some(descs),
                Some(r) => assert_eq!(&descs, r, "{tag}: same answers as streamed @1"),
            }
        }
    }
}

/// The two consumer-side views of the contract — the generation
/// counter and the in-band event — report each change exactly once,
/// at the same place; the arena path skips the events.
#[test]
fn watch_and_event_agree_and_the_arena_path_skips_events() {
    let bytes = spliced();
    let mut dec = decoder(4);
    dec.send_packet(&Packet::new(0, TimeBase::new(1, 25), bytes.clone()))
        .expect("send");
    dec.flush().expect("flush");
    let mut stream = CodecParameters::video(CodecId::new("h265"));
    let mut watch = OutputParamsWatch::new();
    assert!(watch.prime(&*dec, &mut stream), "first shape up front");
    assert_eq!((stream.width, stream.height), (Some(64), Some(48)));
    let (mut by_event, mut by_counter) = (Vec::new(), Vec::new());
    let mut n = 0;
    while let Ok(f) = dec.receive_frame() {
        if watch.observe_frame(&f, &mut stream) {
            by_event.push(n);
        }
        if watch.observe(&*dec, &mut stream) && n > 0 {
            by_counter.push(n);
        }
        if let Frame::Video(vf) = &f {
            assert_eq!(frame_matches(vf, &stream), Some(true), "frame {n}");
            n += 1;
        }
    }
    assert_eq!(n, 56);
    assert_eq!(by_event, EVENTS_AT, "events");
    assert!(
        by_counter.is_empty(),
        "the event already merged each change"
    );
    assert_eq!(dec.output_params_generation(), 5);

    let mut dec = decoder(4);
    dec.send_packet(&Packet::new(0, TimeBase::new(1, 25), bytes))
        .expect("send");
    dec.flush().expect("flush");
    let mut frames = 0;
    let mut generation = 0;
    while let Ok(f) = dec.receive_arena_frame() {
        let _ = f;
        frames += 1;
        generation = dec.output_params_generation();
    }
    assert_eq!(frames, 56, "arena path: frames only");
    assert_eq!(generation, 5);
}

/// The IRAP NAL units (§7.4.2.2 types 16..=21), by index into
/// `nal_payloads`.
fn irap_positions(nals: &[&[u8]]) -> Vec<usize> {
    nals.iter()
        .enumerate()
        .filter(|(_, n)| (16..=21).contains(&nal_type(n)))
        .map(|(i, _)| i)
        .collect()
}

/// The parameter sets (VPS / SPS / PPS) preceding NAL `pos`.
fn parameter_sets_before<'a>(nals: &[&'a [u8]], pos: usize) -> Vec<&'a [u8]> {
    let mut out = Vec::new();
    for &n in &nals[..pos] {
        if matches!(nal_type(n), 32..=34) {
            out.push(n);
        }
    }
    out
}

/// Seek with `reset()`: decode the first `before` NAL units (pulling a
/// little output), reset, then feed the parameter sets and every NAL
/// from IRAP `irap`.
fn seek(before: usize, irap: usize, threads: usize) -> (Vec<Item>, u64) {
    let bytes = spliced();
    let nals = nal_payloads(&bytes);
    let pos = irap_positions(&nals)[irap];
    let mut dec = decoder(threads);
    let (mut items, mut g) = (Vec::new(), 0);
    for n in &nals[..before] {
        dec.send_packet(&annexb(n)).expect("send");
        pull(&mut *dec, &mut items, &mut g, "before the seek");
    }
    assert!(
        items.iter().any(|it| matches!(it, Item::Video { .. })),
        "a frame came out before the seek (else the next shape is the first)"
    );
    let generation = dec.output_params_generation();
    dec.reset().expect("reset");
    assert_eq!(
        dec.output_params_generation(),
        generation,
        "no bump at reset"
    );
    let mut after = Vec::new();
    for n in parameter_sets_before(&nals, pos)
        .into_iter()
        .chain(nals[pos..].iter().copied())
    {
        dec.send_packet(&annexb(n)).expect("send");
        pull(&mut *dec, &mut after, &mut g, "after the seek");
    }
    dec.flush().expect("flush");
    pull(&mut *dec, &mut after, &mut g, "after the flush");
    (after, generation)
}

#[test]
fn reset_rasl_skip_and_flush_follow_the_same_rule() {
    let want = expected();
    let bytes = spliced();
    let nals = nal_payloads(&bytes);
    let iraps = irap_positions(&nals);
    assert_eq!(iraps.len(), 14, "two IRAP pictures per segment");
    // Seek from segment a (64x48 4:2:0 8-bit) into the second IRAP of
    // segment d (64x48 4:2:2 8-bit), a CRA picture: the event comes
    // first, then d's tail — its RASL pictures skipped — and the
    // later segments with their own events.
    let skipped_rasl = nals[iraps[7]..iraps[8]]
        .iter()
        .filter(|n| matches!(nal_type(n), 8 | 9))
        .count();
    for threads in [1, 4] {
        let (after, generation) = seek(iraps[2], 7, threads);
        assert_eq!(generation, 0, "segment a only before the seek");
        let (at, frames) = split(&after);
        assert!(matches!(after[0], Item::Event(_)), "event first: {after:?}");
        let tail = &want[want.len() - frames.len()..];
        assert!(
            skipped_rasl > 0,
            "the seek point is a CRA with RASL pictures"
        );
        assert_eq!(
            frames.len(),
            28 - skipped_rasl,
            "d's second GOP without its RASL pictures, then e, f, g"
        );
        assert_frames(&frames, tail, &format!("seek @{threads}"));
        let d_frames = frames.len() - 24;
        assert_eq!(
            at,
            vec![0, d_frames, d_frames + 8, d_frames + 16],
            "@{threads}: d, e, f, g"
        );
    }
    // Back into the shape already in force (segment g, after decoding
    // to the end): no event at all.
    let (after, generation) = seek(nals.len(), 13, 2);
    assert_eq!(generation, 5);
    let (at, frames) = split(&after);
    assert!(at.is_empty(), "same shape, no event: {at:?}");
    assert_frames(
        &frames,
        &want[want.len() - frames.len()..],
        "seek into the same shape",
    );
}

#[test]
fn encoder_rejects_the_event() {
    let mut p = CodecParameters::video(CodecId::new("h265"));
    p.width = Some(64);
    p.height = Some(48);
    p.pixel_format = Some(PixelFormat::Yuv420P);
    let mut enc = make_encoder(&p).expect("encoder");
    let ev = Frame::StreamParams(Box::new(p.clone()));
    assert!(matches!(enc.send_frame(&ev), Err(Error::Unsupported(_))));
}

/// Decode a multi-layer stream through the registry decoder and check
/// that it makes no spurious announcement: every event changes the
/// description, and every frame of the described layer (the highest
/// output layer) matches the description in force. Returns
/// `(frames, events, shapes)` — `shapes` the number of distinct plane
/// geometries among all the frames, every layer's.
fn multi_layer(
    bytes: &[u8],
    options: &[(&str, String)],
    threads: usize,
    tag: &str,
) -> (usize, usize, usize) {
    let mut params = CodecParameters::video(CodecId::new("h265"));
    for (k, v) in options {
        params.options.insert(*k, v.clone());
    }
    let mut dec = make_decoder(&params).expect("decoder");
    dec.set_execution_context(&ExecutionContext::with_threads(threads));
    dec.send_packet(&Packet::new(0, TimeBase::new(1, 25), bytes.to_vec()))
        .unwrap_or_else(|e| panic!("{tag}: {e}"));
    dec.flush().unwrap_or_else(|e| panic!("{tag}: {e}"));
    let (mut items, mut g) = (Vec::new(), 0);
    pull(&mut *dec, &mut items, &mut g, tag);
    let described = items
        .iter()
        .filter_map(|it| match it {
            Item::Video { layer, .. } => Some(*layer),
            _ => None,
        })
        .max()
        .unwrap_or(0);
    let mut prev: Option<&Desc> = None;
    let (mut frames, mut events) = (0, 0);
    let mut shapes = std::collections::BTreeSet::new();
    for it in &items {
        match it {
            Item::Event(d) => {
                assert_ne!(prev, Some(d), "{tag}: an event that changes nothing");
                assert!(prev.is_some(), "{tag}: an event for the first shape");
                prev = Some(d);
                events += 1;
            }
            Item::Video {
                layer,
                matches,
                geometry,
                desc,
                ..
            } => {
                shapes.insert(geometry.clone());
                if let Some(p) = prev {
                    assert_eq!(p, desc, "{tag}: description moved without an event");
                }
                prev = Some(desc);
                if *layer == described {
                    assert_ne!(*matches, Some(false), "{tag}: described layer geometry");
                }
                frames += 1;
            }
        }
    }
    (frames, events, shapes.len())
}

/// The crate's own layered fixtures: two MV-HEVC views of one size, and
/// a 2x spatially scalable stream outputting both layers (32 and 64
/// wide) — described by its highest output layer from the first frame
/// on, with no event at the layer switch.
#[test]
fn multi_layer_fixtures_emit_no_events() {
    let read = |n: &str| {
        std::fs::read(concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixture_bytes/").to_owned() + n)
            .expect("fixture")
    };
    for threads in [1, 4] {
        assert_eq!(
            multi_layer(&read("r462-mvhevc-3au.hevc"), &[], threads, "mv-hevc"),
            (6, 0, 1)
        );
        assert_eq!(
            multi_layer(&read("r462-shvc-2x.hevc"), &[], threads, "shvc 2x"),
            (2, 0, 2)
        );
    }
    let mut dec = make_decoder(&CodecParameters::video(CodecId::new("h265"))).expect("decoder");
    dec.send_packet(&Packet::new(
        0,
        TimeBase::new(1, 25),
        read("r462-shvc-2x.hevc"),
    ))
    .expect("send");
    dec.flush().expect("flush");
    let mut widths = Vec::new();
    while let Ok(f) = dec.receive_frame() {
        let Frame::Video(vf) = f else {
            panic!("no event expected")
        };
        widths.push((
            vf.layer().map(|l| l.layer_id),
            vf.image_planes()[0].stride,
            dec.output_params().and_then(|p| p.width),
        ));
    }
    assert_eq!(
        widths,
        vec![(Some(0), 32, Some(64)), (Some(1), 64, Some(64))],
        "layer 1 (the highest output layer) is described"
    );
    assert_eq!(dec.output_params_generation(), 0);
}

/// The official MV-HEVC and SHVC conformance bitstreams, when the
/// workspace stages them (`docs/video/h265/conformance/{mv-hevc,shvc}/`;
/// CI checks out this crate alone and skips): decoded through the
/// registry decoder under every staged output layer set, none makes a
/// spurious announcement.
#[test]
fn conformance_multi_layer_streams_emit_no_spurious_events() {
    let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../docs/video/h265/conformance");
    let mut checked = 0;
    let mut with_events = Vec::new();
    // Pairs whose output layers differ in shape: a per-frame
    // description would have changed at every layer switch.
    let mut mixed = 0;
    for sub in ["mv-hevc", "shvc"] {
        let Ok(rd) = std::fs::read_dir(root.join(sub)) else {
            continue;
        };
        let mut streams: Vec<_> = rd
            .flatten()
            .map(|e| e.path())
            .filter(|p| p.extension().is_some_and(|x| x == "bit" || x == "bin"))
            .collect();
        streams.sort();
        for path in streams {
            let stem = path.file_stem().unwrap().to_string_lossy().into_owned();
            // A stream with an external base layer needs it fed
            // through the sequence API (shvc_conformance.rs).
            if stem.starts_with("HYBRID") {
                continue;
            }
            let bytes = std::fs::read(&path).expect("stream");
            // Unoptimised builds check the small streams only.
            if cfg!(debug_assertions) && bytes.len() > 60_000 {
                continue;
            }
            // Every staged output layer set, plus the default target.
            let mut targets: Vec<Vec<(&str, String)>> = vec![vec![]];
            if let Ok(rd) = std::fs::read_dir(root.join(sub)) {
                let mut olss: Vec<usize> = rd
                    .flatten()
                    .filter_map(|e| {
                        let n = e.file_name().to_string_lossy().into_owned();
                        let rest = n.strip_prefix(&stem)?;
                        let rest = rest
                            .strip_prefix("-OLS")
                            .or_else(|| rest.strip_prefix("_OLS"))?;
                        rest.strip_suffix(".opl")?.parse().ok()
                    })
                    .collect();
                olss.sort_unstable();
                targets.extend(olss.into_iter().map(|k| vec![("ols", k.to_string())]));
            }
            for opts in targets {
                let tag = format!("{stem} {opts:?}");
                let (frames, events, shapes) = multi_layer(&bytes, &opts, 4, &tag);
                assert!(frames > 0, "{tag}: no frames");
                checked += 1;
                if shapes > 1 && events == 0 {
                    mixed += 1;
                }
                if events > 0 {
                    with_events.push(format!("{tag}: {events}"));
                }
            }
        }
    }
    if checked > 0 {
        eprintln!(
            "{checked} stream / target pairs, {mixed} with differently shaped output \
             layers and no event; with real changes: {with_events:?}"
        );
    }
}
